public int findLargestSubstring(List<String> strings) {
    int maxLength = 0;
    for (String str : strings) {
        int len = str.length();
        for (int i = 0; i <= len / 2; i++) {
            String prefix = str.substring(i, len - i);
            String suffix = new StringBuilder(prefix).reverse().toString();
            boolean isValid = strings.stream().anyMatch(s -> s.contains(prefix) || s.contains(suffix));
            if (isValid) {
                maxLength = Math.max(maxLength, prefix.length());
            }
        }
    }
    return maxLength;
}

