public String sortString(String s) {
    String result = "";
    int[] count = new int[26];

    // Count the frequency of each character in the string
    for (char c : s.toCharArray()) {
        count[c - 'a']++;
    }

    while (s.length() != result.length()) {
        // Step 1 to 3: Pick the smallest characters
        for (int i = 0; i < 26; i++) {
            if (count[i] > 0) {
                result += (char) (i + 'a');
                count[i]--;
            }
        }

        // Step 4 to 6: Pick the largest characters
        for (int i = 25; i >= 0; i--) {
            if (count[i] > 0) {
                result += (char) (i + 'a');
                count[i]--;
            }
        }
    }

    return result;
}

