    if (n == 0) {
        return "0";
    }
    StringBuilder result = new StringBuilder();
    String number = Integer.toString(n);
    int length = number.length();
    for (int i = 0; i < length; i++) {
        if (i > 0 && (length - i) % 3 == 0) {
            result.append(".");
        }
        result.append(number.charAt(i));
    }
    return result.toString();
}

