public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return new int[0];
    }

    int m = mat.length;
    int n = mat[0].length;
    int[] result = new int[m * n];
    int row = 0, col = 0, d = 0; // d is the direction, 0 for up, 1 for down

    while (row < m && col < n) {
        result[row * n + col] = mat[row][col];

        if (d == 0) {
            if (col == n - 1) {
                row++;
                d = 1;
            } else if (row == 0) {
                col++;
                d = 1;
            } else {
                row--;
                col++;
            }
        } else {
            if (row == m - 1) {
                col++;
                d = 0;
            } else if (col == 0) {
                row++;
                d = 0;
            } else {
                row++;
                col--;
            }
        }
    }

    return result;
}

