    char[] digits = Integer.toString(n).toCharArray();
    int length = digits.length;

    // Start from the right, find the first digit that is smaller than the digit next to it
    int i;
    for (i = length - 2; i >= 0; i--) {
        if (digits[i] < digits[i + 1]) {
            break;
        }
    }

    // If no such digit is found, return -1 (not possible to rearrange)
    if (i == -1) {
        return -1;
    }

    // From the right, find the smallest digit that is greater than digits[i]
    int j;
    for (j = length - 1; j > i; j--) {
        if (digits[j] > digits[i]) {
            break;
        }
    }

    // Swap digits[i] and digits[j]
    char temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;

    // Sort the digits after the (i+1)th position
    Arrays.sort(digits, i + 1, length);

    // Convert the digits back to an integer
    return Integer.parseInt(new String(digits));
}

