public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    for (int i = 1; i <= n; i++) {
        result.add(i);
    }
    result.sort(Comparator.comparingInt(Integer::toString));
    return result;
}

