public static int calculateUniqueSum(int[] nums) {
    int sum = 0;
    boolean[] isUnique = new boolean[nums.length];

    for (int i = 0; i < nums.length; i++) {
        boolean isUniqueElement = true;
        for (int j = 0; j < nums.length; j++) {
            if (i != j && nums[i] == nums[j]) {
                isUniqueElement = false;
                break;
            }
        }
        if (isUniqueElement) {
            sum += nums[i];
        }
    }

    return sum;
}

