public static int minPerfectSquareSum(int n) {
    if (n <= 3) {
        return n;
    }
    int result = n;
    for (int x = 1; x * x <= n; x++) {
        result = Math.min(result, 1 + minPerfectSquareSum(n - x * x));
    }
    return result;
}

